package com.healthwise.dashboard.service;import com.healthwise.analysis.repository.AnalysisHistoryRepository;import com.healthwise.dashboard.dto.DashboardResponse;import com.healthwise.questionnaire.repository.QuestionnaireRepository;import com.healthwise.recommendation.repository.RecommendationRepository;import com.healthwise.report.repository.ReportRepository;import com.healthwise.timeline.service.TimelineService;import org.springframework.stereotype.Service;
/** Reads dashboard information solely from MongoDB. */@Service public class DashboardService{private final QuestionnaireRepository q;private final RecommendationRepository r;private final ReportRepository reports;private final AnalysisHistoryRepository a;private final TimelineService timeline;public DashboardService(QuestionnaireRepository q,RecommendationRepository r,ReportRepository p,AnalysisHistoryRepository a,TimelineService t){this.q=q;this.r=r;reports=p;this.a=a;timeline=t;}public DashboardResponse get(String u){long completed=a.countByUserId(u);long total=r.countByUserId(u);return new DashboardResponse(q.findFirstByUserIdOrderBySubmittedAtDesc(u).orElse(null),r.findFirstByUserIdOrderByGeneratedAtDesc(u).orElse(null),reports.findFirstByUserIdOrderByUploadedAtDesc(u).orElse(null),a.findFirstByUserIdOrderByAnalyzedAtDesc(u).orElse(null),Math.max(0,total-completed),completed,timeline.timeline(u));}}
